      CodeVariant('The starting program compares versions as text. Input lines "package installed fixed". Print "package installed: VULNERABLE" if installed is older than the fixed version (numeric dotted comparison), else OK.', <ProgramCase>[ProgramCase('openssl 3.0.7 3.0.8\nnginx 1.24.0 1.24.0\nlog4j 2.9.1 2.17.1\napp 1.10.0 1.9.0', 'openssl 3.0.7: VULNERABLE\nnginx 1.24.0: OK\nlog4j 2.9.1: VULNERABLE\napp 1.10.0: OK'), ProgramCase('x 10.0 9.9', 'x 10.0: OK'), ProgramCase('y 2.2.9 2.2.10', 'y 2.2.9: VULNERABLE')], starterPy: 'import sys\nfor l in sys.stdin.read().strip().split("\\n"):\n    name, inst, fixed = l.split()\n    print(f"{name} {inst}: {\'VULNERABLE\' if inst < fixed else \'OK\'}")\n'),
