      CodeVariant('Input: line 1 the recorded SHA-256 hash, line 2 the evidence text. Print "SHA-256: <hash>" then MATCH or "MISMATCH - evidence may have been altered".', <ProgramCase>[ProgramCase('74a8d67c0f5f94c4852f4f7592775cc4beab480e340778f60a57f963792f42f7\ninvoice total 4200', 'SHA-256: 74a8d67c0f5f94c4852f4f7592775cc4beab480e340778f60a57f963792f42f7\nMATCH'), ProgramCase('74a8d67c0f5f94c4852f4f7592775cc4beab480e340778f60a57f963792f42f7\ninvoice total 9200', 'SHA-256: 5d1db92189c75d6214a6c51cde1f5b44935a73704e5d1681c62c490c15a12132\nMISMATCH - evidence may have been altered'), ProgramCase('2CF24DBA5FB0A30E26E83B2AC5B9E29E1B161E5C1FA7425E73043362938B9824\nhello', 'SHA-256: 2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824\nMATCH')]),
      CodeVariant('Input: n manifest lines "file hash", then lines "file content". Print "file: OK", "file: MODIFIED" or "file: NOT IN MANIFEST", then "Integrity failures: n".', <ProgramCase>[ProgramCase('2\ninvoice.txt 74a8d67c0f5f94c4852f4f7592775cc4beab480e340778f60a57f963792f42f7\nnotes.txt 03708019b4bad5047e3001a8ae887d7440ee11f8292ed2e6b3b6503ee0d15aa8\ninvoice.txt invoice total 9200\nnotes.txt meeting at 10', 'invoice.txt: MODIFIED\nnotes.txt: OK\nIntegrity failures: 1'), ProgramCase('1\na.txt 2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824\na.txt hello\nb.txt hello', 'a.txt: OK\nb.txt: NOT IN MANIFEST\nIntegrity failures: 1'), ProgramCase('1\nx 2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824\nx hello', 'x: OK\nIntegrity failures: 0')]),
