    CodeProblem(key: 'timeline', title: 'Timeline reconstruction', brief: 'Case 2026-117: build the timeline of a suspected data theft.', skills: const <String>['cs_sec', 'cs_prog'], variants: <CodeVariant>[
      CodeVariant('The starting program prints events in file order. Input lines "YYYY-MM-DDTHH:MM description". Print them in time order.', <ProgramCase>[ProgramCase('2026-03-01T10:15 USB inserted\n2026-03-01T09:58 User logon\n2026-03-01T10:20 Files copied', '2026-03-01T09:58 User logon\n2026-03-01T10:15 USB inserted\n2026-03-01T10:20 Files copied'), ProgramCase('2026-01-02T00:00 b\n2026-01-01T23:59 a', '2026-01-01T23:59 a\n2026-01-02T00:00 b'), ProgramCase('2026-05-05T05:05 only', '2026-05-05T05:05 only')], starterPy: 'import sys\nev = [l.split(" ", 1) for l in sys.stdin.read().strip().split("\\n")]\nfor t, d in ev:\n    print(f"{t} {d}")\n'),
