      CodeVariant('Merge sources recorded in different time zones. Input lines "source local_time offset description" (offset ±HH:MM). Convert to UTC and print "YYYY-MM-DDTHH:MMZ [source] description" in time order.', <ProgramCase>[ProgramCase('fw 2026-03-01T10:05 +00:00 Outbound 2GB to 203.0.113.9\nlaptop 2026-03-01T11:02 +01:00 Archive created\nmail 2026-03-01T04:30 -05:00 Email sent to personal account', '2026-03-01T09:30Z [mail] Email sent to personal account\n2026-03-01T10:02Z [laptop] Archive created\n2026-03-01T10:05Z [fw] Outbound 2GB to 203.0.113.9'), ProgramCase('a 2026-03-01T00:30 +01:00 Login', '2026-02-28T23:30Z [a] Login'), ProgramCase('x 2026-01-01T10:00 +05:30 Start\ny 2026-01-01T04:00 +00:00 Then', '2026-01-01T04:00Z [y] Then\n2026-01-01T04:30Z [x] Start')]),
    ]),
